// ============================================================
// Generator: produce 21 papers x 14 questions = 294 questions
// ============================================================

function generateQuestions(): Question[] {
  const questions: Question[] = [];
  let id = 1;

  const numPapers = 21;
  const lcPerPaper = 6;
  const laPerPaper = 6;
  const lrPerPaper = 1;
  const raPerPaper = 1;

  for (let paper = 1; paper <= numPapers; paper++) {
    const title = `Beijing Exam Practice Paper ${paper}`;

    // Section 1: listen_choose (6 questions, 1.5 pts each = 9)
    for (let i = 0; i < lcPerPaper; i++) {
      const seedIndex = ((paper - 1) * lcPerPaper + i) % lcSeeds.length;
      const seed = lcSeeds[seedIndex];
      questions.push({
        id: id++,
        type: 'listen_choose',
        paper_id: paper,
        section_index: 1,
        difficulty_group: i + 1,
        difficulty_coefficient: parseFloat((1.0 + (paper - 1) * 0.02).toFixed(2)),
        title,
        content: {
          question: seed.question,
          options: seed.options,
          correct_answer: seed.correct,
        },
        audio_script: seed.script,
        max_score: 1.5,
      });
    }

    // Section 2: listen_answer (6 questions, 2 pts each = 12)
    for (let i = 0; i < laPerPaper; i++) {
      const seedIndex = ((paper - 1) * laPerPaper + i) % laSeeds.length;
      const seed = laSeeds[seedIndex];
      questions.push({
        id: id++,
        type: 'listen_answer',
        paper_id: paper,
        section_index: 2,
        difficulty_group: i + 1,
        difficulty_coefficient: parseFloat((1.0 + (paper - 1) * 0.02).toFixed(2)),
        title,
        content: {
          question: seed.question,
          sample_answer: seed.answer,
          keywords: seed.keywords,
        },
        audio_script: seed.script,
        max_score: 2,
      });
    }

    // Section 3: listen_retell (1 question, 10 pts)
    const lrSeed = lrSeeds[(paper - 1) % lrSeeds.length];
    questions.push({
      id: id++,
      type: 'listen_retell',
      paper_id: paper,
      section_index: 3,
      difficulty_group: 1,
      difficulty_coefficient: parseFloat((1.1 + (paper - 1) * 0.02).toFixed(2)),
      title,
      content: {
        topic: lrSeed.topic,
        intro: lrSeed.intro,
        info_points: lrSeed.points,
      },
      audio_script: lrSeed.script,
      max_score: 10,
    });

    // Section 4: read_aloud (1 question, 9 pts)
    const raSeed = raSeeds[(paper - 1) % raSeeds.length];
    questions.push({
      id: id++,
      type: 'read_aloud',
      paper_id: paper,
      section_index: 4,
      difficulty_group: 1,
      difficulty_coefficient: parseFloat((1.0 + (paper - 1) * 0.02).toFixed(2)),
      title,
      content: {
        passage: raSeed.passage,
      },
      audio_script: raSeed.passage,
      max_score: 9,
    });
  }

  return questions;
}

export const questions: Question[] = generateQuestions();

// Pre-computed indices for fast lookup
export const questionsById: Map<number, Question> = new Map(questions.map(q => [q.id, q]));
export const questionsByType: Record<string, Question[]> = questions.reduce((acc, q) => {
  if (!acc[q.type]) acc[q.type] = [];
  acc[q.type].push(q);
  return acc;
}, {} as Record<string, Question[]>);
export const questionsByPaper: Record<number, Question[]> = questions.reduce((acc, q) => {
  if (!acc[q.paper_id]) acc[q.paper_id] = [];
  acc[q.paper_id].push(q);
  return acc;
}, {} as Record<number, Question[]>);

export const papers: { paperId: number; paperTitle: string; typeList: string[]; totalScore: number; questionCount: number }[] = (() => {
  const map = new Map<number, { paperId: number; paperTitle: string; typeList: string[]; totalScore: number; questionCount: number }>();
  for (const q of questions) {
    if (!map.has(q.paper_id)) {
      map.set(q.paper_id, { paperId: q.paper_id, paperTitle: q.title, typeList: [], totalScore: 0, questionCount: 0 });
    }
    const p = map.get(q.paper_id)!;
    if (!p.typeList.includes(q.type)) p.typeList.push(q.type);
    p.totalScore += q.max_score;
    p.questionCount++;
  }
  return Array.from(map.values());
})();
